from common import *

import numpy as np
import random

# concepts:
# color transformation, run modification, recoloring

# description:
# For each horizontal or vertical run of cyan (color-6), recolor up to 3 cells from each end to yellow (color-4).
# The number of cells recolored is capped at half the length of the run.

def main(input_grid: np.ndarray) -> np.ndarray:
    output_grid = np.copy(input_grid)

    # Process horizontal runs
    for row in range(output_grid.shape[0]):
        start = None
        for col in range(output_grid.shape[1]):
            if output_grid[row, col] == Color.TEAL:
                if start is None:
                    start = col
            else:
                if start is not None:
                    end = col - 1
                    recolor_run(output_grid, row, start, end, horizontal=True)
                    start = None
        # Handle the case where the row ends with a teal run
        if start is not None:
            end = output_grid.shape[1] - 1
            recolor_run(output_grid, row, start, end, horizontal=True)

    # Process vertical runs
    for col in range(output_grid.shape[1]):
        start = None
        for row in range(output_grid.shape[0]):
            if output_grid[row, col] == Color.TEAL:
                if start is None:
                    start = row
            else:
                if start is not None:
                    end = row - 1
                    recolor_run(output_grid, col, start, end, horizontal=False)
                    start = None
        # Handle the case where the column ends with a teal run
        if start is not None:
            end = output_grid.shape[0] - 1
            recolor_run(output_grid, col, start, end, horizontal=False)

    return output_grid

def recolor_run(grid: np.ndarray, index: int, start: int, end: int, horizontal: bool):
    length = end - start + 1
    recolor_length = min(3, length // 2)

    if horizontal:
        for i in range(recolor_length):
            grid[index, start + i] = Color.YELLOW
            grid[index, end - i] = Color.YELLOW
    else:
        for i in range(recolor_length):
            grid[start + i, index] = Color.YELLOW
            grid[end - i, index] = Color.YELLOW

def generate_input() -> np.ndarray:
    # Random grid size between 5x5 and 10x10
    rows = random.randint(5, 10)
    cols = random.randint(5, 10)
    grid = np.random.choice(list(Color.NOT_BLACK), (rows, cols))

    # Add random cyan runs
    for _ in range(random.randint(1, 5)):
        horizontal = random.choice([True, False])
        if horizontal:
            row = random.randint(0, rows - 1)
            start = random.randint(0, cols - 3)
            length = random.randint(3, min(6, cols - start))
            grid[row, start:start + length] = Color.TEAL
        else:
            col = random.randint(0, cols - 1)
            start = random.randint(0, rows - 3)
            length = random.randint(3, min(6, rows - start))
            grid[start:start + length, col] = Color.TEAL

    return grid
